	@Test
	void evictsOlderCompletedRunsWithoutChangingFanout(@TempDir File dataDir) {
		var repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("psoc,posc")));
		repository.init();
		try (var connection = repository.getConnection()) {
			ValueFactory vf = SimpleValueFactory.getInstance();
			var detail = vf.createIRI("urn:detail");
			var leaf = vf.createIRI("urn:leaf");
			var key = vf.createIRI("urn:key");
			var root = vf.createIRI("urn:root");
			int keyCount = 12;
			int valuesPerKey = 1_200;
			connection.begin(IsolationLevels.NONE);
			for (int i = 0; i < keyCount; i++) {
				var right = vf.createIRI("urn:right:" + i);
				var child = vf.createIRI("urn:child:" + i);
				connection.add(right, detail, child);
				for (int j = 0; j < valuesPerKey; j++) {
					connection.add(child, leaf, vf.createLiteral(j));
				}
			}
			for (int i = 0; i < keyCount + 2; i++) {
				int rightId = i < keyCount ? i : i == keyCount ? 0 : keyCount - 1;
				var ticket = vf.createIRI("urn:ticket:" + i);
				connection.add(ticket, root, vf.createLiteral(i));
				connection.add(ticket, key, vf.createIRI("urn:right:" + rightId));
			}
			connection.commit();

			var query = connection.prepareTupleQuery(NESTED_OPTIONAL_QUERY.replace("?root <urn:key> ?key .", """
					{ SELECT ?root ?key WHERE { ?ticket <urn:root> ?root; <urn:key> ?key } ORDER BY ?root }
					"""));
			try (var rows = query.evaluate()) {
				for (int i = 0; i < keyCount + 2; i++) {
					for (int j = 0; j < valuesPerKey; j++) {
						assertThat(rows.hasNext()).isTrue();
						var row = rows.next();
						assertThat(row.getValue("root").stringValue()).isEqualTo(Integer.toString(i));
					}
				}
				assertThat(rows.hasNext()).isFalse();
			}
			assertThat(query.explain(Explanation.Level.Telemetry).toString()).contains("optionalRightMemoHitsActual=1");
		} finally {
			repository.shutDown();
		}
	}

